/** 计算报录比（保留一位小数） */
export function toRatioEntries(rows) {
  return rows.map(([major, year, applicants, admitted]) => ({
    major,
    year,
    applicants,
    admitted,
    ratio: Math.round((applicants / admitted) * 10) / 10
  }))
}

/** 获取某校报录比数据（可能为空数组） */
export function ratiosOf(schoolId) {
  const rows = RAW[schoolId]
  return rows ? toRatioEntries(rows) : []
}

/** 有报录比数据的院校 id 列表 */
export const schoolsWithRatios = Object.keys(RAW).filter((id) => RAW[id])
